#!/usr/bin/env bash
# Generated by the ai-plugin-sdk build. Edit the plugin's own sources instead.

# What a settings file says for one key, or nothing. The file is the person's
# own unless another is named. The last assignment of a key is the one that
# counts.
settings_file_value() {
  local key="$1" file="${2:-$PLUGIN_SETTINGS}" value
  [ -f "$file" ] || return 1
  value="$(sed -n "s/^[[:space:]]*${key}[[:space:]]*=[[:space:]]*//p" "$file" \
    | sed 's/[[:space:]]*$//' | tail -n 1)"
  [ -n "$value" ] || return 1
  printf '%s' "$value"
}
